function parseCindyOwnerDecisionOptions(value: string): CindyOwnerDecisionStoredOption[] {
  try {
    const parsed = JSON.parse(value) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((item): item is CindyOwnerDecisionStoredOption => Boolean(
      item && typeof item === 'object'
      && typeof (item as CindyOwnerDecisionStoredOption).optionKey === 'string'
      && ['skip', 'create_candidate', 'append_candidate'].includes((item as CindyOwnerDecisionStoredOption).action),
    )).slice(0, 10);
  } catch {
    return [];
  }
}

function projectCindyOwnerDecision(row: CindyOwnerDecisionRow, sourceCount: number): CindyOwnerDecisionDto {
  return {
    decision_id: row.id,
    status: row.status,
    version: row.version,
    reason_summary: row.reason_summary,
    options: parseCindyOwnerDecisionOptions(row.options_json).map((option) => ({
      option_key: option.optionKey,
      action: option.action,
      title: option.title,
      describe: option.describe,
      next_step: option.nextStep,
      available: option.action !== 'append_candidate'
        || (typeof option.candidateKey === 'string'
          && Number.isInteger(option.candidateVersion) && option.candidateVersion! >= 1
          && option.fieldEvidenceSourceIndexes !== null && option.fieldEvidenceSourceIndexes !== undefined),
    })),
    source_count: sourceCount,
    last_attempt_failed: row.last_error !== null,
    resolution_action: row.resolution_action,
    created_at: row.created_at,
    updated_at: row.updated_at,
    resolved_at: row.resolved_at,
  };
}

const cindyCandidateKeyPattern = /^cnd_[A-Za-z0-9_-]{43}$/u;

function cindyOpaqueKey(auth: CindyAuthContext, kind: 'candidate' | 'conversation' | 'cursor', value: string) {
  return createHmac('sha256', auth.receiptSecret)
    .update(`${kind}\u0000${auth.ownerScope}\u0000${auth.accountAnchor}\u0000${value}`, 'utf8')
    .digest('base64url');
}

function cindyCandidateKey(auth: CindyAuthContext, candidateId: string) {
  return `cnd_${cindyOpaqueKey(auth, 'candidate', candidateId)}`;
}

function cindyConversationKey(auth: CindyAuthContext, chatRef: string, threadRef: string | null) {
  return `cnv_${cindyOpaqueKey(auth, 'conversation', `${chatRef}\u0000${threadRef ?? ''}`)}`;
}

function encodeCindyContextCursor(auth: CindyAuthContext, kind: 'task' | 'candidate', updatedAt: string, rowId: string) {
  const key = createHmac('sha256', auth.receiptSecret)
    .update(`cindy-context-cursor-v1\u0000${auth.ownerScope}\u0000${auth.accountAnchor}`, 'utf8')
    .digest();
  const nonce = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', key, nonce);
  cipher.setAAD(Buffer.from(`cindy-context-cursor-v1\u0000${kind}\u0000${auth.ownerScope}\u0000${auth.accountAnchor}`, 'utf8'));
  const encrypted = Buffer.concat([
    cipher.update(JSON.stringify({ updatedAt, rowId }), 'utf8'),
    cipher.final(),
  ]);
  return `ctx1_${Buffer.concat([nonce, cipher.getAuthTag(), encrypted]).toString('base64url')}`;
}

function decodeCindyContextCursor(auth: CindyAuthContext, kind: 'task' | 'candidate', cursor: string | undefined) {
  if (!cursor) return null;
  try {
    if (!cursor.startsWith('ctx1_')) throw new Error('invalid cursor version');
    const bytes = Buffer.from(cursor.slice(5), 'base64url');
    if (bytes.length <= 28) throw new Error('invalid cursor length');
    const key = createHmac('sha256', auth.receiptSecret)
      .update(`cindy-context-cursor-v1\u0000${auth.ownerScope}\u0000${auth.accountAnchor}`, 'utf8')
      .digest();
    const decipher = createDecipheriv('aes-256-gcm', key, bytes.subarray(0, 12));
    decipher.setAAD(Buffer.from(`cindy-context-cursor-v1\u0000${kind}\u0000${auth.ownerScope}\u0000${auth.accountAnchor}`, 'utf8'));
    decipher.setAuthTag(bytes.subarray(12, 28));
    const parsed = JSON.parse(Buffer.concat([
      decipher.update(bytes.subarray(28)),
      decipher.final(),
    ]).toString('utf8')) as Record<string, unknown>;
    if (typeof parsed.updatedAt !== 'string' || !Number.isFinite(Date.parse(parsed.updatedAt))
      || typeof parsed.rowId !== 'string' || !parsed.rowId) throw new Error('invalid cursor');
    return { updatedAt: parsed.updatedAt, rowId: parsed.rowId };
  } catch {
    throw new CindySourceContractError('INVALID_INPUT', '上下文 cursor 无效或不属于当前认证上下文。');
  }
}

function loadCindyCandidateByKey(database: AppDatabase, auth: CindyAuthContext, candidateKey: string) {
  if (!cindyCandidateKeyPattern.test(candidateKey)) return undefined;
  const rows = database.raw.prepare(
    `SELECT candidate.* FROM candidate_request AS candidate
      WHERE candidate.demand_unit_id IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM cindy_candidate_source_consumption AS consumed
           WHERE consumed.candidate_id = candidate.id
             AND consumed.owner_scope = ? AND consumed.account_anchor = ?
        )
        AND NOT EXISTS (
          SELECT 1 FROM cindy_candidate_source_consumption AS foreign_consumed
           WHERE foreign_consumed.candidate_id = candidate.id
             AND (foreign_consumed.owner_scope <> ? OR foreign_consumed.account_anchor <> ?)
        )`,
  ).all(auth.ownerScope, auth.accountAnchor, auth.ownerScope, auth.accountAnchor) as CandidateRow[];
  return rows.find((candidate) => cindyCandidateKey(auth, candidate.id) === candidateKey);
}

function loadLegacyCindyCandidateByInternalId(database: AppDatabase, auth: CindyAuthContext, candidateId: string) {
  if (!/^cand_[0-9a-f-]{36}$/iu.test(candidateId)) return undefined;
  return database.raw.prepare(
    `SELECT candidate.* FROM candidate_request AS candidate
      WHERE candidate.id = ?
        AND candidate.demand_unit_id IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM cindy_candidate_source_consumption AS consumed
           WHERE consumed.candidate_id = candidate.id
             AND consumed.owner_scope = ? AND consumed.account_anchor = ?
        )
        AND NOT EXISTS (
          SELECT 1 FROM cindy_candidate_source_consumption AS foreign_consumed
           WHERE foreign_consumed.candidate_id = candidate.id
             AND (foreign_consumed.owner_scope <> ? OR foreign_consumed.account_anchor <> ?)
        )
        AND candidate.state IN ('pending','snoozed')
        AND candidate.deleted_at IS NULL AND candidate.accepted_task_id IS NULL
        AND candidate.merged_into_candidate_id IS NULL`,
  ).get(candidateId, auth.ownerScope, auth.accountAnchor, auth.ownerScope, auth.accountAnchor) as CandidateRow | undefined;
}

function loadProjectedCindyOwnerDecision(database: AppDatabase, decisionId: string): CindyOwnerDecisionDto {
  const row = database.raw.prepare(
    `SELECT decision.*,
            (SELECT COUNT(*) FROM cindy_owner_decision_source AS source WHERE source.decision_id = decision.id) AS source_count
       FROM cindy_owner_decision AS decision WHERE decision.id = ?`,
  ).get(decisionId) as (CindyOwnerDecisionRow & { source_count: number }) | undefined;
  if (!row) throw new CindySourceContractError('CONFLICT', '主人决定状态无法读取。');
  return projectCindyOwnerDecision(row, row.source_count);
}

const nowIso = () => new Date().toISOString();
const id = (prefix: string) => prefix + '_' + randomUUID();

type DraftOnlyState = 'draft' | 'rejected' | 'obsolete';

function stableJson(value: unknown): string {
  if (value === null || typeof value !== 'object') return JSON.stringify(value) ?? 'null';
  if (Array.isArray(value)) return `[${value.map((item) => stableJson(item)).join(',')}]`;
  const object = value as Record<string, unknown>;
  return `{${Object.keys(object).sort().map((key) => `${JSON.stringify(key)}:${stableJson(object[key])}`).join(',')}}`;
}

function draftOnlyApprovalState(status: unknown): DraftOnlyState {
  if (status === 'awaiting_approval') return 'draft';
  if (status === 'rejected') return 'rejected';
  return 'obsolete';
}

function draftOnlyOutboxState(status: unknown): DraftOnlyState {
  return status === 'awaiting_approval' ? 'draft' : 'obsolete';
}

function safeDraftActionType(value: unknown) {
  return typeof value === 'string' && /^[A-Za-z0-9_.:-]{1,100}$/u.test(value) ? value : 'redacted_action';
}

function approvalDraftDto(row: Record<string, unknown>) {
  const status = row.status === 'awaiting_approval'
    ? 'awaiting_approval'
    : row.status === 'rejected'
      ? 'rejected'
      : 'obsolete';
  return {
    id: typeof row.id === 'string' ? row.id : 'redacted_approval',
    action_type: safeDraftActionType(row.action_type),
    status,
    state: draftOnlyApprovalState(row.status),
    created_at: typeof row.created_at === 'string' ? row.created_at : null,
    decided_at: typeof row.decided_at === 'string' ? row.decided_at : null,
    externally_sent: false,
  };
}

function outboxDraftDto(row: Record<string, unknown>) {
  return {
    id: typeof row.id === 'string' ? row.id : 'redacted_outbox',
    approval_id: typeof row.approval_id === 'string' ? row.approval_id : 'redacted_approval',
    action_type: safeDraftActionType(row.action_type),
    state: draftOnlyOutboxState(row.status),
    created_at: typeof row.created_at === 'string' ? row.created_at : null,
    externally_sent: false,
  };
}
const maxFeishuMonitorPeople = 5000;
const maxFeishuPeoplePerRun = 50;
const maxFeishuMonitorGroups = 50;

function objectValue(value: unknown) {
  return value && typeof value === 'object' ? value as Record<string, unknown> : {};
}

function firstText(value: unknown, ...keys: string[]) {
  const record = objectValue(value);
  for (const key of keys) {
    const item = record[key];
    if ((typeof item === 'string' || typeof item === 'number') && String(item).trim()) return String(item).trim();
  }
  return '';
}

